#!/usr/bin/env python3
"""Place measured speech on one time axis; write narration.wav and timeline.json (new files only)."""
import json, subprocess, wave
from pathlib import Path
import numpy as np
WORK = Path(__file__).resolve().parents[1]
HEAD, SAME, SCENE, TAIL, RATE = 1.2, 0.3, 0.8, 5.0, 48000
script = json.loads((WORK/"source/script.json").read_text())
act = json.loads((WORK/"audio/activity.json").read_text())
out_wav, out_json = WORK/"audio/narration.wav", WORK/"source/timeline.json"
for p in (out_wav, out_json):
    if p.exists(): raise SystemExit(f"exists, refusing to overwrite: {p}")
def pcm(path):
    raw = subprocess.check_output(["ffmpeg","-v","error","-i",str(path),"-ac","1","-ar",str(RATE),"-f","s16le","-"])
    return np.frombuffer(raw, np.int16)
t, pieces, segs, prev = HEAD, [], [], None
for s in script:
    a = act[s["id"]]
    if prev is not None:
        t += SCENE if prev != s["scene"] else SAME
    lo, hi = max(0, a["on"]-0.04), min(a["total"], a["off"]+0.12)
    x = pcm(WORK/"audio"/f"{s['id']}.ogg")[int(lo*RATE):int(hi*RATE)]
    pieces.append((int(round(t*RATE)), x))
    segs.append({**{k: s[k] for k in ("id","scene","display")}, "start": round(t+(a["on"]-lo),3), "end": round(t+len(x)/RATE,3)})
    t += len(x)/RATE; prev = s["scene"]
total = t + TAIL
buf = np.zeros(int(round(total*RATE)), np.int32)
for at, x in pieces: buf[at:at+len(x)] += x
buf = np.clip(buf, -32768, 32767).astype(np.int16)
with wave.open(str(out_wav), "wb") as w:
    w.setnchannels(1); w.setsampwidth(2); w.setframerate(RATE); w.writeframes(buf.tobytes())
json.dump({"fps": 30, "duration": round(total,3), "segments": segs}, open(out_json,"w"), ensure_ascii=False, indent=1)
print("duration", round(total,2))
for s in segs: print(s["id"], s["scene"], s["start"], s["end"])
#!/usr/bin/env python3
"""Measure speech onset/offset in each segment (-45 dBFS, 20 ms windows)."""
import json, subprocess, sys
from pathlib import Path
import numpy as np
WORK = Path(__file__).resolve().parents[1]
def pcm(path):
    raw = subprocess.check_output(["ffmpeg","-v","error","-i",str(path),"-ac","1","-ar","48000","-f","s16le","-"])
    return np.frombuffer(raw, np.int16).astype(np.float32) / 32768
out = {}
for seg in json.loads((WORK/"source/script.json").read_text()):
    x = pcm(WORK/"audio"/f"{seg['id']}.ogg"); w = 960
    rms = np.sqrt(np.mean(x[:len(x)//w*w].reshape(-1, w)**2, axis=1) + 1e-12)
    active = np.where(20*np.log10(rms) > -45)[0]
    out[seg["id"]] = {"total": len(x)/48000, "on": active[0]*w/48000, "off": (active[-1]+1)*w/48000}
json.dump(out, open(WORK/"audio/activity.json","w"), indent=1)
speech = sum(v["off"]-v["on"] for v in out.values())
for k,v in out.items(): print(k, f"on {v['on']:.2f} off {v['off']:.2f} of {v['total']:.2f}")
print("speech total", round(speech,1))
