from pathlib import Path
HERE = Path(__file__).resolve().parent
WORK = HERE.parent
TTS = WORK.parents[1] / "tools/video/scripts/jianying_direct.py"
SPEAKER = "ICL_zh_male_zhuzhuxia"
log = []
for seg in json.loads((HERE / "script.json").read_text()):
    out = WORK / "audio" / f"{seg['id']}.ogg"
