        continue
    with tempfile.TemporaryDirectory() as t:
        sp, dp = Path(t) / "s.txt", Path(t) / "d.txt"
        sp.write_text(seg["spoken"]); dp.write_text(seg["display"])
        r = subprocess.run([sys.executable, str(TTS), "tts", "--speaker", SPEAKER, "--text-file", str(sp),
