    if r.returncode:
        sys.exit(f"{seg['id']} failed: {r.stderr[-800:]}")
    info = json.loads(r.stdout.strip().splitlines()[-1])
    log.append({"id": seg["id"], "speaker": SPEAKER, "sha256": info["sha256"], "pronunciation": info["pronunciation"]["status"]})
    print(seg["id"], "ok", flush=True)
p = WORK / "audio" / "synthesis-log.json"
old = json.loads(p.read_text()) if p.exists() else []
p.write_text(json.dumps(old + log, ensure_ascii=False, indent=1))
