#!/usr/bin/env python3
"""Machine checks for the final MP4: spec, full decode, audio identity vs master, A/V duration,
and frames at every subtitle midpoint for viewing. Writes a NEW JSON report and frame folder."""
import json, subprocess, sys
from pathlib import Path
import numpy as np
W = Path(__file__).resolve().parents[1]
final, report, frames = Path(sys.argv[1]), Path(sys.argv[2]), Path(sys.argv[3])
for p in (report, frames):
    if p.exists(): sys.exit(f"exists: {p}")
info = json.loads(subprocess.check_output(["ffprobe", "-v", "error", "-show_streams", "-show_format", "-of", "json", str(final)]))
v = next(s for s in info["streams"] if s["codec_type"] == "video")
a = next(s for s in info["streams"] if s["codec_type"] == "audio")
decode = subprocess.run(["ffmpeg", "-v", "error", "-xerror", "-i", str(final), "-f", "null", "-"], capture_output=True, text=True)

def pcm(path):
    raw = subprocess.check_output(["ffmpeg", "-v", "error", "-i", str(path), "-ac", "1", "-ar", "48000", "-f", "s16le", "-"])
    return np.frombuffer(raw, np.int16).astype(np.float32) / 32768
master, enc = pcm(W / "audio/narration.wav"), pcm(final)
n = min(len(master), len(enc))
lag = int(np.argmax(np.correlate(enc[:48000 * 8], master[:48000 * 4], "valid")))  # encoder delay
m, e = master[:n - lag], enc[lag:n]
corr = float(np.dot(m, e) / (np.linalg.norm(m) * np.linalg.norm(e)))
tl = json.loads((W / "source/timeline.json").read_text())
frames.mkdir()
for s in tl["segments"]:
    t = (s["start"] + s["end"]) / 2
    subprocess.run(["ffmpeg", "-v", "error", "-ss", f"{t:.3f}", "-i", str(final), "-frames:v", "1",
                    "-vf", "scale=1280:-1", str(frames / f"{s['id']}-{t:06.2f}.jpg")], check=True)
result = {
    "file": str(final), "bytes": final.stat().st_size,
    "video": {k: v.get(k) for k in ("codec_name", "width", "height", "r_frame_rate", "nb_frames", "pix_fmt", "duration")},
    "audio": {k: a.get(k) for k in ("codec_name", "sample_rate", "channels", "duration")},
    "timeline_duration": tl["duration"], "full_decode_errors": decode.stderr.strip() or None,
    "audio_vs_master": {"correlation": round(corr, 6), "encoder_lag_samples": lag,
                        "master_seconds": round(len(master) / 48000, 3), "encoded_seconds": round(len(enc) / 48000, 3)},
    "frames_for_viewing": str(frames), "not_checked": ["normal-speed playback", "subjective listening", "author acceptance"],
}
report.write_text(json.dumps(result, ensure_ascii=False, indent=1))
print(json.dumps(result, ensure_ascii=False, indent=1))
