a = next(s for s in info["streams"] if s["codec_type"] == "audio")
decode = subprocess.run(["ffmpeg", "-v", "error", "-xerror", "-i", str(final), "-f", "null", "-"], capture_output=True, text=True)

def pcm(path):
    raw = subprocess.check_output(["ffmpeg", "-v", "error", "-i", str(path), "-ac", "1", "-ar", "48000", "-f", "s16le", "-"])
    return np.frombuffer(raw, np.int16).astype(np.float32) / 32768
master, enc = pcm(W / "audio/narration.wav"), pcm(final)
n = min(len(master), len(enc))
lag = int(np.argmax(np.correlate(enc[:48000 * 8], master[:48000 * 4], "valid")))  # encoder delay
m, e = master[:n - lag], enc[lag:n]
corr = float(np.dot(m, e) / (np.linalg.norm(m) * np.linalg.norm(e)))
