// Native Remotion input/output; no task state, approvals or delivery manifests.
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {parseArgs} from 'node:util';
import {bundle} from '@remotion/bundler';
import {getCompositions, renderMedia, renderStill} from '@remotion/renderer';
import {executablePath} from '../../browser.mjs';
import {requireAbsent, commitFile} from '../../output-safe.mjs';

const {values,positionals}=parseArgs({allowPositionals:true,options:{
  props:{type:'string'},assets:{type:'string'},composition:{type:'string'},frames:{type:'string'},
  still:{type:'string'},mute:{type:'boolean'},concurrency:{type:'string',default:'1'},gl:{type:'string'},help:{type:'boolean'}
}});
if(values.help||positionals.length!==2){
  console.log('node tools/video/scripts/render.mjs ENTRY.jsx OUTPUT.mp4 [--props props.json] [--assets DIR] [--composition ID] [--frames FIRST,LAST] [--mute]\nPNG: ENTRY.jsx OUTPUT.png --composition Cover --still 0\nExisting files are never replaced.');
  process.exit(values.help?0:1);
}
const [entry,output]=positionals.map(p=>path.resolve(p));
requireAbsent(output);
if(!fs.statSync(entry).isFile())throw new Error('Entry must be a source file');
const concurrency=Number(values.concurrency);
if(!Number.isInteger(concurrency)||concurrency<1)throw new Error('concurrency must be a positive integer');
if(values.still!==undefined&&values.frames)throw new Error('Use still or frames');
const inputProps=values.props?JSON.parse(fs.readFileSync(path.resolve(values.props),'utf8')):{};
const runtime=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
fs.mkdirSync(path.dirname(output),{recursive:true});
const temporary=fs.mkdtempSync(path.join(path.dirname(output),'.render-'));
const candidate=path.join(temporary,path.basename(output));
let completed=false;
try{
  const serveUrl=await bundle({entryPoint:entry,publicDir:values.assets?path.resolve(values.assets):null,
    outDir:path.join(temporary,'bundle'),rootDir:runtime,enableCaching:false,
    webpackOverride:config=>({...config,resolve:{...config.resolve,modules:[path.join(runtime,'node_modules'),'node_modules']}})});
  const chromiumOptions=values.gl?{gl:values.gl}:{};
  const common={serveUrl,inputProps,browserExecutable:executablePath,chromiumOptions,timeoutInMilliseconds:180000};
  const compositions=await getCompositions(common.serveUrl,common);
  const composition=values.composition?compositions.find(c=>c.id===values.composition):compositions.length===1?compositions[0]:null;
  if(!composition)throw new Error('Select --composition from: '+compositions.map(c=>c.id).join(', '));
  const validFrame=f=>Number.isInteger(f)&&f>=0&&f<composition.durationInFrames;
  if(values.still!==undefined){
    const frame=Number(values.still);
    if(!validFrame(frame)||path.extname(output).toLowerCase()!=='.png')throw new Error('still requires a valid frame and PNG output');
    await renderStill({...common,composition,frame,imageFormat:'png',output:candidate,overwrite:false});
  }else{
    const frameRange=values.frames?values.frames.split(',').map(Number):undefined;
    if(frameRange&&(frameRange.length!==2||!frameRange.every(validFrame)||frameRange[0]>frameRange[1]))throw new Error('Invalid inclusive frame range');
    if(path.extname(output).toLowerCase()!=='.mp4')throw new Error('Video output must be MP4');
    await renderMedia({...common,composition,frameRange,codec:'h264',outputLocation:candidate,
      overwrite:false,concurrency,muted:values.mute??false,crf:19,x264Preset:'fast'});
  }
  commitFile(candidate,output);completed=true;
  console.log(JSON.stringify({output,composition:composition.id,width:composition.width,height:composition.height,fps:composition.fps,frames:values.still!==undefined?1:values.frames?Number(values.frames.split(',')[1])-Number(values.frames.split(',')[0])+1:composition.durationInFrames}));
}catch(error){
  fs.writeFileSync(path.join(temporary,'error.txt'),String(error.stack||error));
  console.error('Failure evidence:',temporary);throw error;
}finally{if(completed)fs.rmSync(temporary,{recursive:true,force:true});}

