// 你看到的颜色，有三分之二是猜的 —— 3840x2160 / 30 fps, laid out in 1920x1080 units, scaled x2.
// Timing comes from props.timeline (measured narration). Every picture of the photo is a real
// computation from source/demosaic.py: truth.png, mosaic.png (RGGB samples), guess.png (bilinear).
import React, {useEffect, useState} from 'react';
import {AbsoluteFill, Composition, Img, continueRender, delayRender, interpolate, registerRoot,
  staticFile, useCurrentFrame, Easing} from 'remotion';

const C = {bg: '#0D0E11', panel: '#17191E', ink: '#F2F0EA', soft: '#9A978F', line: '#2A2D34',
  R: '#FF4D4D', G: '#3DDC6A', B: '#4D7DFF', warm: '#FFB15C'};
const SANS = '"Noto Sans SC", sans-serif', MONO = '"JetBrains Mono", "Noto Sans SC", monospace';
const FPS = 30;
const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'};
const ease = Easing.bezier(0.2, 0.7, 0.2, 1);
const inout = Easing.bezier(0.65, 0, 0.35, 1);
const rise = (t, at, dur = 0.5) => interpolate(t, [at, at + dur], [0, 1], {...clamp, easing: ease});
const glide = (t, at, dur) => interpolate(t, [at, at + dur], [0, 1], {...clamp, easing: inout});
const fmt = (n) => n.toLocaleString('en-US');
const CH = ['R', 'G', 'B'];

const useFonts = () => {
  const [handle] = useState(() => delayRender('fonts'));
  useEffect(() => {
    const faces = [['Noto Sans SC', 'NotoSansSC.ttf', '100 900'], ['JetBrains Mono', 'Mono.ttf', '100 800']]
      .map(([f, file, w]) => new FontFace(f, `url(${staticFile(file)})`, {weight: w}));
    Promise.all(faces.map((f) => f.load())).then((loaded) => {
      loaded.forEach((f) => document.fonts.add(f));
      continueRender(handle);
    });
  }, [handle]);
};

const seg = (tl, id) => tl.segments.find((s) => s.id === id);
const sceneSpan = (tl, scene) => {
  const list = tl.segments.filter((s) => s.scene === scene);
  const i = tl.segments.indexOf(list[0]);
  const prev = tl.segments[i - 1];
  const next = tl.segments[tl.segments.indexOf(list[list.length - 1]) + 1];
  return [prev ? (prev.end + list[0].start) / 2 : 0, next ? (list[list.length - 1].end + next.start) / 2 : tl.duration];
};

// The photo frame: 1440x810 units, i.e. 1280x720 image pixels at 1.125 units each.
const FX = 240, FY = 56, FW = 1440, FH = 810, K = FW / 1280;
const Photo = ({src, style}) => (
  <Img src={staticFile(src)} style={{position: 'absolute', left: 0, top: 0, width: FW, height: FH,
    imageRendering: 'pixelated', ...style}} />
);
const Frame = ({children, style}) => (
  <div style={{position: 'absolute', left: FX, top: FY, width: FW, height: FH, overflow: 'hidden',
    borderRadius: 6, background: '#000', ...style}}>{children}</div>
);
const Tag = ({children, color = C.ink, style}) => (
  <div style={{position: 'absolute', fontFamily: SANS, fontWeight: 700, fontSize: 30, color,
    background: 'rgba(13,14,17,0.82)', padding: '8px 18px', borderRadius: 8, ...style}}>{children}</div>
);
const Note = ({children, o = 1, style}) => (
  <div style={{position: 'absolute', fontFamily: SANS, fontSize: 19, color: C.soft, opacity: o, ...style}}>{children}</div>
);

const Subtitle = ({tl, t}) => {
  const s = tl.segments.find((x) => t >= x.start - 0.08 && t <= x.end + 0.15);
  if (!s) return null;
  return (
    <div style={{position: 'absolute', left: 0, right: 0, bottom: 40, display: 'flex', justifyContent: 'center'}}>
      <div style={{maxWidth: 1600, padding: '10px 26px', background: 'rgba(0,0,0,0.78)', color: '#FFFFFF',
        fontFamily: SANS, fontWeight: 600, fontSize: 40, lineHeight: 1.42, textAlign: 'center', borderRadius: 10}}>
        {s.display}
      </div>
    </div>
  );
};

// ---------- the 16x9 pixel close-up ----------
const CELL = FW / 16;
const cellColor = (c, mode) => {
  if (mode === 'truth') return `rgb(${c.rgb.join(',')})`;
  const v = [0, 0, 0]; v[c.c] = c.v;
  return `rgb(${v.join(',')})`;
};
const Grid = ({zoom, t, filters = 0, only = 0, numbers = 0, unknown = 0, dim = 0, focus}) => (
  <div style={{position: 'absolute', inset: 0}}>
    {zoom.block.map((row, y) => row.map((c, x) => {
      const isFocus = focus && focus.some(([fx, fy]) => fx === x && fy === y);
      const fade = focus && !isFocus ? dim : 0;
      return (
        <div key={`${x}-${y}`} style={{position: 'absolute', left: x * CELL, top: y * CELL, width: CELL, height: CELL,
          background: only ? cellColor(c, 'only') : cellColor(c, 'truth'), opacity: 1 - fade * 0.7}}>
          <div style={{position: 'absolute', inset: 0, background: cellColor(c, 'truth'), opacity: 1 - only}} />
          <div style={{position: 'absolute', inset: 3, border: `3px solid ${C[CH[c.c]]}`, borderRadius: 6, opacity: filters}} />
          <div style={{position: 'absolute', left: 10, top: 8, fontFamily: MONO, fontWeight: 700, fontSize: 18,
            color: C[CH[c.c]], opacity: filters, textShadow: '0 0 6px #000'}}>{CH[c.c]}</div>
          <div style={{position: 'absolute', left: 0, right: 0, top: 34, textAlign: 'center', fontFamily: MONO,
            fontWeight: 700, fontSize: 24, color: '#fff', opacity: numbers, textShadow: '0 0 6px #000'}}>{c.v}</div>
          <div style={{position: 'absolute', left: 0, right: 0, top: 62, textAlign: 'center', fontFamily: MONO,
            fontSize: 15, color: 'rgba(255,255,255,0.7)', opacity: unknown}}>
            {CH.filter((_, i) => i !== c.c).map((n) => `${n}?`).join(' ')}
          </div>
        </div>
      );
    }))}
  </div>
);

// zoom from the whole photo into the block: origin at block centre (image units), scale up to 80x
const zoomStyle = (zoom, p) => {
  const cx = (zoom.x + zoom.w / 2) * K, cy = (zoom.y + zoom.h / 2) * K;
  const s = Math.pow(FW / (zoom.w * K), p);
  return {transformOrigin: `${cx}px ${cy}px`, transform: `translate(${(FW / 2 - cx) * p}px, ${(FH / 2 - cy) * p}px) scale(${s})`};
};

// ---------- scenes ----------
const Hook = ({t, tl}) => {
  const s = seg(tl, 's01');
  return (
    <AbsoluteFill>
      <Frame style={{opacity: rise(t, 0.2, 0.8)}}>
        <Photo src="truth.png" style={{transform: `scale(${1.06 - 0.06 * glide(t, 0, 7)})`}} />
      </Frame>
      <div style={{position: 'absolute', left: FX + 60, top: FY + 70, opacity: rise(t, s.start + 3.2)}}>
        <div style={{fontFamily: SANS, fontWeight: 900, fontSize: 150, color: '#fff', lineHeight: 1,
          textShadow: '0 4px 30px rgba(0,0,0,0.5)'}}>2/3</div>
        <div style={{fontFamily: SANS, fontWeight: 800, fontSize: 54, color: '#fff', marginTop: 10,
          textShadow: '0 4px 20px rgba(0,0,0,0.5)'}}>的颜色是猜的</div>
      </div>
    </AbsoluteFill>
  );
};

const Zoom = ({t, tl, zoom}) => {
  const s2 = seg(tl, 's02'), s3 = seg(tl, 's03');
  const p = glide(t, s2.start, 2.6);
  const grid = rise(t, s2.start + 2.4, 0.4);
  return (
    <AbsoluteFill>
      <Frame>
        <div style={{position: 'absolute', inset: 0, ...zoomStyle(zoom, p), opacity: 1 - grid}}>
          <Photo src="truth.png" />
        </div>
        <div style={{opacity: grid}}>
          <Grid zoom={zoom} t={t} filters={rise(t, s2.start + 3.6, 0.6)} only={glide(t, s3.start + 0.2, 1.0)}
            numbers={rise(t, s3.start + 1.0)} unknown={rise(t, s3.start + 2.6)} />
        </div>
      </Frame>
      <Tag style={{left: FX + 24, top: FY + 24, opacity: grid * (1 - rise(t, s2.start + 3.4, 0.3))}}>放大：16 × 9 个像素</Tag>
      <Tag style={{left: FX + 24, top: FY + 24, opacity: rise(t, s2.start + 3.6) * (1 - rise(t, s3.start, 0.3))}}>
        每格一片滤镜：<span style={{color: C.R}}>红</span> · <span style={{color: C.G}}>绿</span> · <span style={{color: C.B}}>蓝</span>
      </Tag>
      <Tag style={{left: FX + 24, top: FY + 24, opacity: rise(t, s3.start + 0.3)}}>每格只量到 1 个数，另外 2 个不知道</Tag>
    </AbsoluteFill>
  );
};

const Counter = ({label, value, ratio, color, o}) => (
  <div style={{opacity: o, marginBottom: 46}}>
    <div style={{fontFamily: SANS, fontSize: 26, color: C.soft}}>{label}</div>
