const Mosaic = ({t, tl, zoom, needed, measured, size}) => {
  const s4 = seg(tl, 's04'), s5 = seg(tl, 's05');
  const [a] = sceneSpan(tl, 'mosaic');
  const back = glide(t, a, 1.4);              // zoom back out over the mosaic
  const shrink = glide(t, s5.start, 0.9);     // make room for the counts
  const n = (from, to, at) => Math.round(interpolate(t, [at, at + 1.2], [from, to], {...clamp, easing: ease}));
  return (
    <AbsoluteFill>
      <Frame style={{left: FX - (FX - 70) * shrink, top: FY + 80 * shrink, transform: `scale(${1 - 0.25 * shrink})`,
        transformOrigin: '0 0'}}>
        <div style={{position: 'absolute', inset: 0, ...zoomStyle(zoom, 1 - back)}}><Photo src="mosaic.png" /></div>
      </Frame>
      <Tag style={{left: FX + 24, top: FY + 24, opacity: rise(t, s4.start) * (1 - shrink)}}>传感器实际记录：每格一种颜色</Tag>
      <div style={{position: 'absolute', left: 1190, top: 170, width: 620}}>
        <Counter o={rise(t, s5.start + 0.4)} label={`全彩需要 ${size[0]} × ${size[1]} × 3`}
          value={fmt(n(0, needed, s5.start + 0.4))} ratio={1} color={C.ink} />
        <Counter o={rise(t, s5.start + 3.6)} label="传感器量到" value={fmt(n(0, measured, s5.start + 3.6))}
          ratio={measured / needed} color={C.warm} />
        <div style={{fontFamily: SANS, fontSize: 30, color: C.ink, opacity: rise(t, s5.start + 5.2)}}>
          剩下 <span style={{fontFamily: MONO, fontWeight: 800, color: C.warm}}>{fmt(needed - measured)}</span> 个，靠猜
        </div>
      </div>
    </AbsoluteFill>
  );
};

const Guess = ({t, tl, zoom, example: ex}) => {
  const s6 = seg(tl, 's06'), s7 = seg(tl, 's07');
  const focus = [[ex.x, ex.y], [ex.x, ex.y - 1], [ex.x - 1, ex.y], [ex.x + 1, ex.y], [ex.x, ex.y + 1]];
  const fill = rise(t, s6.start + 4.2, 0.6);
  const out = glide(t, s7.start - 0.1, 0.8);   // grid -> whole image
  const wipe = glide(t, s7.start + 0.7, 2.4);
  const c = zoom.block[ex.y][ex.x];
  return (
    <AbsoluteFill>
      <Frame>
        <div style={{position: 'absolute', inset: 0, opacity: 1 - out}}>
          <Grid zoom={zoom} t={t} filters={1} only={1} numbers={1} dim={rise(t, s6.start + 1.6)} focus={focus} />
          <div style={{position: 'absolute', left: ex.x * CELL, top: ex.y * CELL, width: CELL, height: CELL,
            background: `rgb(${c.v},${ex.guess},0)`, opacity: fill, display: 'flex', alignItems: 'center', justifyContent: 'center',
            boxShadow: `0 0 0 4px ${C.G}`}}>
            <span style={{fontFamily: MONO, fontWeight: 800, fontSize: 22, color: '#fff', textShadow: '0 0 6px #000'}}>G≈{ex.guess}</span>
          </div>
          <div style={{position: 'absolute', left: 560, top: 360, width: 820, padding: '28px 34px', background: 'rgba(13,14,17,0.9)',
            borderRadius: 14, opacity: rise(t, s6.start + 2.0)}}>
            <div style={{fontFamily: SANS, fontSize: 26, color: C.soft}}>这一格量到红 {ex.red}，绿是多少？看四个绿邻居：</div>
            <div style={{fontFamily: MONO, fontWeight: 700, fontSize: 40, color: C.ink, marginTop: 14}}>
              ({ex.neighbours.join(' + ')}) / 4 ≈ <span style={{color: C.G}}>{ex.guess}</span>
            </div>
            <div style={{fontFamily: SANS, fontSize: 22, color: C.soft, marginTop: 12, opacity: rise(t, s6.start + 4.8)}}>
              真值 {ex.truth}。平滑的地方，取平均就够准。
            </div>
          </div>
        </div>
        <div style={{position: 'absolute', inset: 0, opacity: out}}>
          <Photo src="mosaic.png" />
          <div style={{position: 'absolute', inset: 0, clipPath: `inset(0 ${100 - wipe * 100}% 0 0)`}}><Photo src="guess.png" /></div>
          <div style={{position: 'absolute', top: 0, bottom: 0, left: `${wipe * 100}%`, width: 3, background: '#fff',
            opacity: wipe > 0 && wipe < 1 ? 0.9 : 0}} />
        </div>
      </Frame>
      <Tag style={{left: FX + 24, top: FY + 24, opacity: rise(t, s6.start) * (1 - out)}}>猜：看邻居，取平均</Tag>
      <Tag style={{left: FX + 24, top: FY + 24, opacity: rise(t, s7.start + 2.8)}}>猜完的照片</Tag>
    </AbsoluteFill>
  );
};

const Crop = ({src, box, left, label, color, o}) => {
  const W = 780, s = W / box.w;
  return (
    <div style={{position: 'absolute', left, top: 120, opacity: o}}>
      <div style={{width: W, height: box.h * s, overflow: 'hidden', borderRadius: 8, position: 'relative', background: '#000'}}>
        <Img src={staticFile(src)} style={{position: 'absolute', left: -box.x * s, top: -box.y * s, width: 1280 * s,
          height: 720 * s, imageRendering: 'pixelated'}} />
      </div>
      <div style={{fontFamily: SANS, fontWeight: 700, fontSize: 34, color, marginTop: 18}}>{label}</div>
    </div>
  );
};

const FalseColor = ({t, tl, falsebox: fb}) => {
  const s8 = seg(tl, 's08'), s9 = seg(tl, 's09');
  const [a] = sceneSpan(tl, 'false');
  const split = glide(t, s8.start + 1.4, 1.0);
  const bx = fb.x * K, by = fb.y * K, bw = fb.w * K, bh = fb.h * K;
  return (
    <AbsoluteFill>
      <Frame style={{opacity: 1 - split}}>
        <Photo src="guess.png" />
        <div style={{position: 'absolute', left: bx, top: by, width: bw, height: bh, border: '3px solid #fff',
          borderRadius: 4, opacity: rise(t, a + 0.3)}} />
      </Frame>
      <Crop src="truth.png" box={fb} left={150} label="真实：白栏杆，没有彩色" color={C.ink} o={split} />
      <Crop src="guess.png" box={fb} left={990} label="猜出来的：红黄蓝条纹" color={C.warm} o={split} />
      <div style={{position: 'absolute', left: 990, top: 680, opacity: rise(t, s9.start)}}>
        <div style={{fontFamily: SANS, fontWeight: 900, fontSize: 84, color: C.warm, lineHeight: 1}}>伪色</div>
      </div>
      <Note o={rise(t, s9.start + 1.5)} style={{left: 150, top: 700, width: 760, lineHeight: 1.6}}>
        这里用的是最简单的双线性插值。手机 ISP 会看边缘方向、用更复杂的模型，伪色少得多，但依然是在估计。
      </Note>
    </AbsoluteFill>
  );
};

const BayerTile = ({n = 8, size = 64, o = 1, hiG = 0}) => (
  <div style={{position: 'relative', width: n * size, height: n * size, opacity: o}}>
    {Array.from({length: n * n}, (_, i) => {
      const x = i % n, y = Math.floor(i / n);
      const c = y % 2 === 0 ? (x % 2 === 0 ? 0 : 1) : (x % 2 === 0 ? 1 : 2);
      const dim = hiG && c !== 1 ? hiG * 0.75 : 0;
      return <div key={i} style={{position: 'absolute', left: x * size, top: y * size, width: size - 4, height: size - 4,
        borderRadius: 6, background: C[CH[c]], opacity: 1 - dim}} />;
    })}
  </div>
);

const Bayer = ({t, tl}) => {
  const s10 = seg(tl, 's10'), s11 = seg(tl, 's11');
  const hiG = rise(t, s11.start + 0.2) * (1 - rise(t, s11.start + 4.4));
  return (
    <AbsoluteFill>
      <div style={{position: 'absolute', left: 170, top: 150}}><BayerTile o={rise(t, s10.start - 0.3)} hiG={hiG} /></div>
      <div style={{position: 'absolute', left: 820, top: 150, width: 960}}>
        <div style={{background: C.panel, border: `1px solid ${C.line}`, borderRadius: 14, padding: '34px 40px',
          opacity: rise(t, s10.start + 0.6)}}>
          <div style={{fontFamily: MONO, fontWeight: 800, fontSize: 54, color: C.ink}}>US 3,971,065</div>
          <div style={{fontFamily: MONO, fontSize: 32, color: C.ink, marginTop: 10}}>Color imaging array</div>
          <div style={{fontFamily: SANS, fontSize: 28, color: C.soft, marginTop: 22, lineHeight: 1.6}}>
            发明人 Bryce E. Bayer · Eastman Kodak<br />1975-03-05 申请 · <span style={{color: C.ink}}>1976-07-20 授权</span>
          </div>
        </div>
        <div style={{display: 'flex', gap: 46, marginTop: 44, fontFamily: MONO, fontWeight: 800, fontSize: 48,
          opacity: rise(t, s11.start + 0.2)}}>
          <span style={{color: C.R}}>R 25%</span><span style={{color: C.G}}>G 50%</span><span style={{color: C.B}}>B 25%</span>
        </div>
        <div style={{fontFamily: SANS, fontSize: 26, color: C.soft, marginTop: 14, opacity: rise(t, s11.start + 1.2)}}>
          人眼对亮度细节最敏感的波段在绿光附近
        </div>
        <div style={{fontFamily: SANS, fontWeight: 900, fontSize: 96, color: C.ink, marginTop: 40, opacity: rise(t, s11.start + 5.0)}}>
          1976 <span style={{color: C.soft}}>→</span> 2026 <span style={{fontSize: 56, color: C.warm}}>50 年</span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

const Eye = ({t, tl}) => {
  const s12 = seg(tl, 's12'), s13 = seg(tl, 's13'), s14 = seg(tl, 's14'), s15 = seg(tl, 's15');
  const [a] = sceneSpan(tl, 'eye');
  const quote = glide(t, s15.start - 0.2, 0.8);
  const D = 640;
  return (
    <AbsoluteFill>
      <div style={{position: 'absolute', left: 170, top: 214, opacity: rise(t, a) * (1 - rise(t, s13.start, 0.6))}}>
        <BayerTile n={8} size={64} />
        <div style={{fontFamily: SANS, fontSize: 28, color: C.soft, marginTop: 20}}>相机传感器</div>
      </div>
      <div style={{position: 'absolute', left: 800, top: 250, fontFamily: SANS, fontSize: 90, color: C.soft,
        opacity: rise(t, s12.start + 1.2) * (1 - rise(t, s13.start, 0.6))}}>≈</div>
      <div style={{position: 'absolute', left: interpolate(glide(t, s13.start, 1), [0, 1], [1040, 170]), top: 150,
        opacity: rise(t, s12.start + 1.2) * (1 - quote * 0.75)}}>
        <div style={{width: D, height: D, borderRadius: D / 2, overflow: 'hidden', position: 'relative'}}>
          <Img src={staticFile('cones.png')} style={{width: D * 1.5, height: D * 1.5, position: 'absolute', left: -D / 4, top: -D / 4,
            transform: `scale(${1 + 0.08 * glide(t, a, 22)})`}} />
        </div>
        <div style={{fontFamily: SANS, fontSize: 22, color: C.soft, marginTop: 18, textAlign: 'center', width: D}}>
          视网膜视锥细胞排列 · 程序示意图，非真实影像
        </div>
      </div>
      <div style={{position: 'absolute', left: 900, top: 190, width: 880, opacity: rise(t, s13.start + 0.8) * (1 - quote)}}>
        {[['L', '长波', C.R], ['M', '中波', C.G], ['S', '短波', C.B]].map(([k, n, col]) => (
          <div key={k} style={{display: 'flex', alignItems: 'center', gap: 22, marginBottom: 26}}>
            <div style={{width: 46, height: 46, borderRadius: 23, background: col}} />
            <div style={{fontFamily: SANS, fontSize: 38, color: C.ink}}>{k} 视锥 · {n}</div>
          </div>
        ))}
        <div style={{fontFamily: SANS, fontSize: 30, color: C.soft, marginTop: 6}}>每一个，只认一种</div>
        <div style={{marginTop: 54, padding: '26px 32px', background: C.panel, border: `1px solid ${C.line}`, borderRadius: 14,
          opacity: rise(t, s14.start + 0.3)}}>
          <div style={{fontFamily: MONO, fontSize: 26, color: C.ink, lineHeight: 1.5}}>Roorda &amp; Williams<br />Nature 397, 520–522 (1999)</div>
          <div style={{fontFamily: SANS, fontSize: 24, color: C.soft, marginTop: 12}}>首次在活体人眼中拍到 L / M / S 视锥的排列</div>
        </div>
      </div>
      <div style={{position: 'absolute', left: 170, right: 170, top: 250, opacity: quote}}>
        <div style={{fontFamily: SANS, fontWeight: 800, fontSize: 64, color: C.ink, lineHeight: 1.4}}>
          “在很小的尺度上，色觉正常的人，<br />也必然是<span style={{color: C.warm}}>色盲</span>。”
        </div>
        <div style={{fontFamily: MONO, fontSize: 27, color: C.soft, marginTop: 36, lineHeight: 1.5}}>
          observers with normal trichromatic colour vision are<br />necessarily colour blind on a local spatial scale.
        </div>
        <div style={{fontFamily: SANS, fontSize: 22, color: C.soft, marginTop: 18}}>— Roorda &amp; Williams, Nature, 1999，摘要</div>
      </div>
    </AbsoluteFill>
  );
};

const End = ({t, tl}) => {
  const s16 = seg(tl, 's16'), s17 = seg(tl, 's17'), s18 = seg(tl, 's18');
  const toMosaic = glide(t, s17.start + 1.6, 1.2);
  const back = glide(t, s17.start + 4.2, 2.6);
  const card = glide(t, s18.end + 0.4, 1.0);
  return (
    <AbsoluteFill>
      <Frame style={{opacity: 1 - card * 0.85}}>
        <Photo src="guess.png" />
        <div style={{position: 'absolute', inset: 0, opacity: toMosaic * (1 - back)}}><Photo src="mosaic.png" /></div>
        <div style={{position: 'absolute', inset: 0, background: 'rgba(255,170,80,0.10)', opacity: back}} />
      </Frame>
      <Tag style={{left: FX + 24, top: FY + 24, opacity: rise(t, s16.start + 0.4) * (1 - rise(t, s17.start, 0.4))}}>
        相机在猜 · 眼睛也在猜
      </Tag>
      <Tag style={{left: FX + 24, top: FY + 24, opacity: rise(t, s17.start + 1.6) * (1 - rise(t, s17.start + 4.2, 0.4))}}>
        几个真实的瞬间
      </Tag>
      <Tag color={C.warm} style={{left: FX + 24, top: FY + 24, opacity: rise(t, s17.start + 4.6) * (1 - card)}}>
        剩下的，你补上的颜色
      </Tag>
      <div style={{position: 'absolute', left: 0, right: 0, top: 330, textAlign: 'center', opacity: card}}>
        <div style={{fontFamily: SANS, fontWeight: 900, fontSize: 96, color: C.ink}}>三分之二的颜色，是猜的</div>
        <div style={{fontFamily: SANS, fontSize: 40, color: C.warm, marginTop: 28}}>猜出来的颜色，带着偏爱</div>
      </div>
    </AbsoluteFill>
  );
};

const SCENES = {hook: Hook, zoom: Zoom, mosaic: Mosaic, guess: Guess, false: FalseColor, bayer: Bayer, eye: Eye, end: End};

const Film = (props) => {
  useFonts();
  const {timeline: tl} = props;
  const t = useCurrentFrame() / FPS;
  const scenes = [...new Set(tl.segments.map((s) => s.scene))];
  return (
    <AbsoluteFill style={{background: C.bg}}>
      <div style={{width: 1920, height: 1080, transform: 'scale(2)', transformOrigin: '0 0', position: 'relative'}}>
        {scenes.map((name) => {
          const [a, b] = sceneSpan(tl, name);
          if (t < a - 0.35 || t > b + 0.35) return null;
          const o = Math.min(rise(t, a - 0.35, 0.35), 1 - rise(t, b, 0.35));
          const S = SCENES[name];
          return <AbsoluteFill key={name} style={{opacity: o}}><S t={t} {...props} tl={tl} /></AbsoluteFill>;
        })}
        <Subtitle tl={tl} t={t} />
      </div>
    </AbsoluteFill>
  );
};

registerRoot(() => (
  <Composition id="Film" component={Film} width={3840} height={2160} fps={FPS}
    durationInFrames={1} calculateMetadata={({props}) => ({durationInFrames: Math.ceil(props.timeline.duration * FPS)})}
    defaultProps={{timeline: {duration: 1 / FPS, segments: []}}} />
));

